            ? `${need.stage} →「${currentModule.label}」`
            : `${need.stage} →平稳期`;
          const nextText = nextStage
            ? `；相邻下一阶段 ${nextStage}${nextModule ? ` →「${nextModule.label}」` : ' →应急期'}`
            : '；已是最高阶段';
          lines.push(`- ${name}·${NEED_LABELS[needKey]}：${currentText}${nextText}`);
        }
      }
      if (!current.reproductive || !isPlainObject(character?.reproductive)) continue;
      const pregnancy = character.reproductive.pregnancy;
      if (isPlainObject(pregnancy) && Number.isInteger(pregnancy.gestation_days)) {
        const title = pregnancyRouteTitle(pregnancy.gestation_days);
        if (title) lines.push(`- ${name}·pregnancy：gestation_days=${pregnancy.gestation_days} →「${title}」`);
      } else {
        const cycle = character.reproductive.menstrual_cycle;
        if (isPlainObject(cycle) && Number.isInteger(cycle.cycle_day)) {
